def maskPII(S: str) -> str:
    if '@' in S:
        name, domain = S.split('@')
        name = name[0] + '*' * 5 + name[-1]
        return name.lower() + '@' + domain.lower()
    else:
        digits = [c for c in S if c.isdigit()]
        local_number = '***-***-' + ''.join(digits[-4:])
        if len(digits) == 10:
            return local_number
        else:
            return '+' + '*' * (len(digits) - 10) + '-' + local_number
